import { useCallback, useEffect, useRef } from 'react'
import { connect } from 'react-redux'
import get from 'lodash/get'
import { isEmpty } from 'lodash/lang'
import { InnerForm } from '../../../../../components'
import AddressForm from '../../../../../components/AddressForm'
import propertyActions from '../../../../../redux/property/actions'
import { LANG_STRINGS } from '../../../../../lang'
import {
  getIndividualCustomerDataForm,
  getCorporateCustomerDataForm,
  mapIndividualCustomerDataForm,
  mapCorporateCustomerDataForm
} from '../../constants'

const addressLabelsMap = {
  'individual': {
    province: LANG_STRINGS.province,
    city: LANG_STRINGS.city,
    postalCode: LANG_STRINGS.postalCode,
    address: LANG_STRINGS.address,
    addressPlaceholder: LANG_STRINGS.addressExample,
  },
  'corporate': {
    province: LANG_STRINGS.province,
    city: LANG_STRINGS.city,
    postalCode: LANG_STRINGS.postalCode,
    address: LANG_STRINGS.addressCorporate,
    addressPlaceholder: LANG_STRINGS.addressExample,
  },
}

function CustomerDataForm (props) {
  const {
    handleGetSubmitMethods, policyDetails, onGuideClick,
    onCustomerAddressChange, onCustomerFormChange,
    getPropertyCorporateType, propertyCorporateType
  } = props

  const individualCustomerFormRef = useRef(null)
  const corporateCustomerFormRef = useRef(null)
  const customerAddrSubmitRef = useRef(null)

  const isIndividualCustomer = policyDetails?.customer_data?.type === 'individual'
  const isCorporateCustomer = policyDetails?.customer_data?.type === 'corporate'

  useEffect(() => {
    // fetch on first render
    getPropertyCorporateType()
  }, [getPropertyCorporateType])

  const handleSubmit = useCallback(async (e) => {
    if (isIndividualCustomer) {
      const individualCustomerData = await individualCustomerFormRef.current.handleSubmit(e)
      const customerAddress = await customerAddrSubmitRef.current(e)
      if (isEmpty(individualCustomerData) || isEmpty(customerAddress)) return
      return mapIndividualCustomerDataForm({
        customerData: individualCustomerData,
        customerAddress,
        policyDetails
      })
    }
    if (isCorporateCustomer) {
      const corporateCustomerData = await corporateCustomerFormRef.current.handleSubmit(e)
      const customerAddress = await customerAddrSubmitRef.current(e)
      if (isEmpty(corporateCustomerData) || isEmpty(customerAddress)) return
      return mapCorporateCustomerDataForm({
        customerData: corporateCustomerData,
        customerAddress,
        policyDetails,
        corporateTypeList: propertyCorporateType?.corporate_type_list,
        economicActivityList: propertyCorporateType?.economic_activity_list,
      })
    }
  }, [policyDetails, isIndividualCustomer, isCorporateCustomer, propertyCorporateType])

  const handleGetAddressSubmit = useCallback((type, onSubmit, getAddr) => {
    customerAddrSubmitRef.current = onSubmit
  }, [])

  useEffect(() => {
    handleGetSubmitMethods('customer-data-form', handleSubmit)
  }, [handleGetSubmitMethods, handleSubmit])

  return (
    <>
      {isIndividualCustomer && (
        <InnerForm
          ref={individualCustomerFormRef}
          formData={getIndividualCustomerDataForm(policyDetails)}
          onGuideClick={onGuideClick}
          onInputChange={onCustomerFormChange}
        />
      )}
      {isCorporateCustomer && (
        <InnerForm
          ref={corporateCustomerFormRef}
          formData={getCorporateCustomerDataForm(policyDetails, {
            corporateTypeList: propertyCorporateType?.corporate_type_list,
            economicActivityList: propertyCorporateType?.economic_activity_list,
          })}
          onGuideClick={onGuideClick}
          onInputChange={onCustomerFormChange}
        />
      )}
      <AddressForm
        addressType='customer-address'
        address={get(policyDetails, 'customer_data.customer_address', {})}
        labels={addressLabelsMap[policyDetails?.customer_data?.type]}
        handleGetAddressSubmit={handleGetAddressSubmit}
        onAddressChange={onCustomerAddressChange}
      />
    </>
  )
}
const { getPropertyCorporateType } = propertyActions

export default connect(
  (state) => ({
    propertyCorporateType: state.Property.propertyCorporateType,
  }),
  {
    getPropertyCorporateType
  }
)(CustomerDataForm)
