export const getIndividualCustomerDataForm = (data) => {
  let mobile = data.customer_data?.mobile_no || ''
  if (mobile && mobile.includes('62-')) {
    mobile = mobile.substring(3, mobile.length)
  }
  return {
    fields: [
      {
        type: 'upload',
        name: 'ktp',
        label: LANG_STRINGS.ktpKitasPhoto,
        defaultValue: data.customer_data?.ktp_url,
        error: ERROR_LANG.ktpError,
        guide: true,
      },
      {
        type: 'ktp',
        name: 'ktp_no',
        label: LANG_STRINGS.ktpKitasNumber,
        placeholder: LANG_STRINGS.ktpKitasNumber,
        defaultValue: data.customer_data?.ktp_no,
        minLength: 16,
        maxLength: 16,
        className: 'input-field',
      },
      {
        type: 'input',
        name: 'name',
        label: LANG_STRINGS.ktpKitasName,
        placeholder: LANG_STRINGS.ktpKitasName,
        defaultValue: data.customer_data?.name,
      },
      {
        type: 'input',
        name: 'birth_place',
        label: LANG_STRINGS.placeOfBirth,
        placeholder: LANG_STRINGS.placeOfBirth,
        defaultValue: data.customer_data?.birth_place,
      },
      {
        type: 'dob',
        name: 'birth_date',
        label: LANG_STRINGS.dateOfBirth,
        placeholder: LANG_STRINGS.dateOfBirth,
        defaultValue: parseDateFromApi(data.customer_data?.birth_date),
      },
      {
        type: 'select',
        name: 'gender',
        label: LANG_STRINGS.gender,
        placeholder: `Pilih ${LANG_STRINGS.gender}`,
        defaultValue: data.customer_data?.gender,
        data: [
          { value: 'male', display: 'Pria' },
          { value: 'female', display: 'Wanita' },
        ],
        dataKey: 'value',
        displayKey: 'display',
      },
      {
        type: 'select',
        name: 'marital_status',
        label: LANG_STRINGS.maritalStatus,
        placeholder: `Pilih ${LANG_STRINGS.maritalStatus}`,
        defaultValue: data.customer_data?.marital_status,
        data: [
          { value: 'single', display: 'Belum Kawin' },
          { value: 'married', display: 'Kawin' },
          { value: 'divorced', display: 'Cerai Hidup' },
          { value: 'widowed', display: 'Cerai Mati' },
        ],
        dataKey: 'value',
        displayKey: 'display',
      },
      {
        type: 'phone_number',
        name: 'mobile_no',
        label: LANG_STRINGS.customerPhone,
        placeholder: PROPERTY_LANG.phoneNumberPlaceholder,
        defaultValue: mobile,
        className: 'customer-phone-input',
        subTitle: PROPERTY_LANG.phoneNumberSubtitle,
        regexValidation: regex.propertyPhoneNumber,
        regexErrorMessage: PROPERTY_LANG.phoneNumberRegexError,
      },
      {
        type: 'email',
        name: 'email',
        label: LANG_STRINGS.emailAddress,
        placeholder: LANG_STRINGS.emailAddress,
        defaultValue: data.customer_data?.email,
      },
    ],
  }
}

export const mapIndividualCustomerDataForm = ({
  customerData,
  customerAddress,
  policyDetails,
}) => {
  return {
    customer_data: {
      ...(policyDetails.customer_data || {}),
      name: customerData.name,
      mobile_no: customerData.mobile_no,
      email: customerData.email,
      birth_place: customerData.birth_place,
      birth_date: formatDateToApi(customerData.birth_date),
      gender: customerData.gender,
      marital_status: customerData.marital_status,
      customer_address: {
        ...(policyDetails.customer_data?.customer_address || {}),
        province_name: customerAddress.province_name,
        province_code: customerAddress.province_code,
        province_code_data: customerAddress.province_code_data,
        city_name: customerAddress.city_name,
        city_code: customerAddress.city_code,
        city_code_data: customerAddress.city_code_data,
        region: customerAddress.region,
        postal_code: customerAddress.postal_code,
        address: customerAddress.address,
      },
      ktp_url:
        typeof customerData.ktp === 'object'
          ? customerData.ktp.ktp
          : customerData.ktp,
      ktp_no: customerData.ktp_no,
    },
    ktp_url:
      typeof customerData.ktp === 'object'
        ? customerData.ktp.ktp
        : customerData.ktp,
    ktp_no: customerData.ktp_no,
  }
}

