export const mapCorporateCustomerDataForm = ({
  customerData,
  customerAddress,
  policyDetails,
  corporateTypeList,
  economicActivityList,
}) => {
  const corporateTypeData =
    find(corporateTypeList, { code: customerData.corporate_type }) || {}
  const economicActivityData =
    find(economicActivityList, { code: customerData.economic_activity }) || {}
  return {
    customer_data: {
      ...(policyDetails.customer_data || {}),
      corporate_data: {
        ...(policyDetails.customer_data?.corporate_data || {}),
        name: customerData.corporate_name,
        npwp_url:
          typeof customerData.npwp === 'object'
            ? customerData.npwp.npwp
            : customerData.npwp,
        npwp_no: customerData.npwp_no,
        corporate_type: corporateTypeData.code,
        corporate_type_data: corporateTypeData,
        economic_activity: economicActivityData.code,
        economic_activity_data: economicActivityData,
        founding_date: formatDateToApi(customerData.founding_date),
        country_of_origin: customerData.country_of_origin,
        pic_name: customerData.pic_name,
        pic_mobile_no: customerData.pic_mobile_no,
        pic_email: customerData.pic_email,
      },
      customer_address: {
        ...(policyDetails.customer_data?.customer_address || {}),
        province_name: customerAddress.province_name,
        province_code: customerAddress.province_code,
        province_code_data: customerAddress.province_code_data,
        city_name: customerAddress.city_name,
        city_code: customerAddress.city_code,
        city_code_data: customerAddress.city_code_data,
        region: customerAddress.region,
        postal_code: customerAddress.postal_code,
        address: customerAddress.address,
      },
    },
  }
}

