import get from 'lodash/get'
import isObject from 'lodash/isObject'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { DisplayFlexRCC, Row } from '../../../commonStyle/index.style'
import { Button, CustomText } from '../../../components'
import CustomCheckbox from '../../../components/CustomCheckbox'
import HardCopySection from '../../../components/HardCopySection'
import ImageGuideModal from '../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import ShowSnackbar from '../../../components/ShowNotification'
import SingleImgContainer from '../../../components/SingleImgContainer'
import Textarea from '../../../components/Textarea'
import TitleError from '../../../components/TitleError'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { KTP_IMG, NPWP_IMG, LIGHT_GOLD_BULB } from '../../../images'
import { LANG_STRINGS } from '../../../lang'
import { useSaveCustomerData } from '../../../state/globalState/hooks/useGlobalContext'
import TermsNConditionModal from '../../Private/Application/components/TermsNConditionModal'
import { PROPERTY_LANG } from '../../Private/Property/lang'
import BuildingImgSection from './components/BuildingImgSection'
import CustomerDataForm from './components/CustomerDataForm'
import { BUILDING_IMGS, BUILDING_IMG_GUIDE } from './constants'
import { BuildingImgGuideStyle, PropertyFormStyle } from './index.style'

function PropertyDetailForm (props) {
  const { policyDetails, onSubmitForm, id } = props
  const [imageGuideParams, setImageGuideParams] = useState({})
  const [showTermsModal, setShowTermsModal] = useState(false)
  const [isTermsChecked, setIsTermsChecked] = useState(false)
  const [propertyAddress, setPropertyAddress] = useState(policyDetails?.property_address || '')
  const [propertyAddressError, setPropertyAddressError] = useState('')
  const savedCustomerDataToGlobalStore = useSaveCustomerData()
  const customerDataFormSubmit = useRef()

  const isCustomerForm = useMemo(() => {
    return window.location.href.includes('customer/')
  }, [])

  useEffect(() => {
    if (policyDetails) {
      savedCustomerDataToGlobalStore({
        customer_name: policyDetails?.customer_data?.name,
        mobile_no: policyDetails?.customer_data?.mobile_no,
        customer_address: policyDetails?.customer_data?.customer_address
      })
    }
  }, [savedCustomerDataToGlobalStore, policyDetails])

  const handleOpenImgModal = useCallback((containerType, params) => {
    let imgContainer = ''
    let modalTitle = ''
    let btmTitle = ''

    switch (containerType) {
      case 'ktp':
        imgContainer = (
          <SingleImgContainer
            title={LANG_STRINGS.photoKTP}
            imgUrl={KTP_IMG}
            titlePosition='up'
            titleAlign='start'
          />
        )
        modalTitle = LANG_STRINGS.ktpPhotoGuide
        btmTitle = LANG_STRINGS.makeSureKTPPhotoClear
        break
      case 'npwp':
        imgContainer = (
          <SingleImgContainer
            title={LANG_STRINGS.photoNPWP}
            imgUrl={NPWP_IMG}
            titlePosition='up'
            titleAlign='start'
          />
        )
        modalTitle = LANG_STRINGS.npwpPhotoGuide
        btmTitle = LANG_STRINGS.makeSureNPWPPhotoClear
        break
      case 'building':
        imgContainer = (
          <BuildingImgGuideStyle>
            {
              BUILDING_IMG_GUIDE.map(guide => (
                <Row align='center' justify='space-between' key={guide.title1}>
                  <SingleImgContainer
                    title={guide.title1}
                    imgUrl={guide.img1}
                    height='119px'
                    titleAlign='center'
                    titlePosition='up'
                    imgClassName='build-guide-img'
                  />
                  <SingleImgContainer
                    title={guide.title2}
                    imgUrl={guide.img2}
                    height='119px'
                    titlePosition='up'
                    imgClassName='build-guide-img'
                    titleAlign='center'
                  />
                </Row>
              ))
            }
          </BuildingImgGuideStyle>
        )
        modalTitle = PROPERTY_LANG.buildingPhotoGuide
        btmTitle = PROPERTY_LANG.makeSureImgsAreClear
        break
      default:
        break
    }
    setImageGuideParams({
      showImgModal: !imageGuideParams.showImgModal,
      modalImgContainer: imgContainer,
      modalTitle: modalTitle,
      modalBottomTitle: btmTitle
    })
  }, [imageGuideParams])

  const handleCloseImgModal = () => {
    setImageGuideParams({
      showImgModal: false,
      modalImgContainer: '',
      modalTitle: ''
    })
  }

  const handleCustomerAddressChange = useCallback((customerAddress) => {
    savedCustomerDataToGlobalStore({
      customer_address: customerAddress
    })
  }, [savedCustomerDataToGlobalStore])

  const handleCustomerFormChange = useCallback((value, name) => {
    const key = (name === 'name') ? 'customer_name' : name
    savedCustomerDataToGlobalStore({
      [key]: value
    })
  }, [savedCustomerDataToGlobalStore])

  const handleToggleTermsModal = () => {
    setShowTermsModal(!showTermsModal)
  }

  const handleTermsCheckBox = (useCase) => {
    setIsTermsChecked(useCase)
    setShowTermsModal(false)
  }

  const handlePropertyAddressChange = (e) => {
    setPropertyAddress(e.target.value)
    setPropertyAddressError('')
  }

  const handleSubmit = useCallback(async (e) => {
    const customerData = await customerDataFormSubmit.current(e)
    let hardCopyData = {}
    if (policyDetails?.package_data?.hard_copy_enabled) {
      hardCopyData = await HardCopySection.getHardCopyData(e)
    }
    const images = {}
    let isValidHardCopy = true
    if (hardCopyData.hard_copy_required && !hardCopyData.isValid) {
      isValidHardCopy = false
    }

    if (!propertyAddress) {
      setPropertyAddressError(LANG_STRINGS.required)
      return
    }

    BUILDING_IMGS.forEach(buildingImg => {
      // images is an object of type
      // { image_1: url, image_2: url}
      images[buildingImg.type] = buildingImg.images
    })

    if (customerData && isValidHardCopy) {
      const finalData = {
        ...policyDetails,
        ...images,
        code: policyDetails.code,
        ...customerData,
        property_address: propertyAddress,
        location: propertyAddress, // TODO: remove if not required
        hard_copy_required: false,
        ...hardCopyData
      }
      onSubmitForm(finalData)
    }
  }, [policyDetails, propertyAddress, onSubmitForm])

  const handleGetSubmitMethods = useCallback((formType, method) => {
    switch (formType) {
      case 'customer-data-form':
        customerDataFormSubmit.current = method
        break
      default:
        break
    }
  }, [])

  return (
    <PropertyFormStyle>
      <div className='section'>
        <CustomText
          size='16px'
          weight={800}
          color={AgentColorPallette.mustard}
        >
          {PROPERTY_LANG.insuredData}
        </CustomText>
        <CustomerDataForm
          policyDetails={policyDetails}
          handleGetSubmitMethods={handleGetSubmitMethods}
          onGuideClick={(field) => handleOpenImgModal(field.name)}
          onCustomerAddressChange={handleCustomerAddressChange}
          onCustomerFormChange={handleCustomerFormChange}
        />
      </div>
      <div className='separator' />
      <div className='section'>
        <CustomText
          size='16px'
          weight={800}
          color={AgentColorPallette.mustard}
        >
          {PROPERTY_LANG.insuredObjectData}
        </CustomText>
        <TitleError
          title={PROPERTY_LANG.insuredObjectLocation}
          error={propertyAddressError}
          required
        />
        <Textarea
          name='property_address'
          placeholder={LANG_STRINGS.addressExample}
          defaultValue={propertyAddress}
          errorField={propertyAddressError && 'property_address'}
          onChange={handlePropertyAddressChange}
          resize='vertical'
        />
      </div>
      <div className='separator' />
      <div className='section'>
        <Row align='center' justify='space-between'>
          <CustomText
            size='16px'
            weight={800}
            color={AgentColorPallette.mustard}
          >
            {PROPERTY_LANG.buildingPhotos} (Optional)
          </CustomText>
          <Row align='center' onClick={() => { handleOpenImgModal('building') }}>
            <CustomText
              color={AgentColorPallette.darkerGold}
              weight={700}
            >
              {LANG_STRINGS.guide}
            </CustomText>
            &nbsp;&nbsp;
            <img src={LIGHT_GOLD_BULB} alt='' />
          </Row>
        </Row>
        {
          BUILDING_IMGS.map(imgSection => (
            <BuildingImgSection
              key={imgSection.type}
              title={imgSection.title}
              type={imgSection.type}
              defaultImgs={get(policyDetails, `[${imgSection.type}]`, {})}
              images={imgSection.images}
            />
          ))
        }
      </div>
      <div className='separator' />
      <div className='section-hard-copy'>
        {
          policyDetails?.package_data?.hard_copy_enabled &&
            <HardCopySection
              isHideSendToPP={
                isObject(policyDetails?.provider_branch)
                  ? !policyDetails?.provider_branch?.tags?.includes('HEADQUARTER')
                  : false
              }
              isCustomerForm={isCustomerForm}
              preFilledData={{
                hard_copy_required: policyDetails?.hard_copy_required,
                hard_copy_sent_to: policyDetails?.hard_copy_sent_to,
                customer_address: policyDetails?.customer_data?.customer_address,
                customer_name: policyDetails?.customer_data?.name,
                mobile_no: policyDetails?.customer_data?.mobile_no,
                hard_copy_address: policyDetails?.hard_copy_address,
                hard_copy_recipient: policyDetails?.hard_copy_recipient,
                hard_copy_recipient_mobile: policyDetails?.hard_copy_recipient_mobile
              }}
              proposedAdminFee={0} // no additional fee for TM
              isHardCopyRequired={policyDetails?.package_data?.always_charge_hard_copy}
            />
        }
      </div>
      <div className='bottom-action-container'>
        <DisplayFlexRCC className='bottom-terms-condition'>
          <CustomCheckbox
            isChecked={isTermsChecked}
            onChange={handleToggleTermsModal}
            name='propertyTerm'
            id='propertyTermsOnForm'
          />
          <CustomText
            onClick={handleToggleTermsModal}
            color={AgentColorPallette.black}
            dangerouslySetInnerHTML={{
              __html: LANG_STRINGS.agreeWithTermsConditions
            }}
          />
        </DisplayFlexRCC>
        <DisplayFlexRCC className='bottom-continue-btn'>
          <Button
            onClick={handleSubmit}
            disabled={!isTermsChecked}
            id={`${id}-Submit${isTermsChecked ? 'Enabled' : 'Disabled'}`}
          >
            {LANG_STRINGS.next}
          </Button>
        </DisplayFlexRCC>
      </div>
      <ImageGuideModal
        showImgModal={imageGuideParams.showImgModal}
        title={imageGuideParams.modalTitle}
        onClose={handleCloseImgModal}
        modalImgContainer={imageGuideParams.modalImgContainer}
        bottomTitle={imageGuideParams.modalBottomTitle}
      />
      {
        showTermsModal && (
          <TermsNConditionModal
            isOpen={showTermsModal}
            tncData={policyDetails.package_data?.tnc?.data}
            onAccept={() => handleTermsCheckBox(true)}
            onReject={() => handleTermsCheckBox(false)}
            isNewStructure
          />
        )
      }
      <ShowSnackbar hideOkay />
    </PropertyFormStyle>
  )
}

export default PropertyDetailForm
